#!/usr/bin/env bash
# Starts the validators generated by setup.sh as local processes.
# Node i listens for P2P on 30302+i and JSON-RPC on 8544+i (node1 = 8545).
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BESU="${BESU:-besu}"
HEAP="${BESU_HEAP:-1g}"
N=$(ls -d "$HERE"/data/node* | wc -l)
mkdir -p "$HERE/logs"

pub1=$(sed 's/^0x//' "$HERE/data/node1/key.pub")
BOOTNODE="enode://${pub1}@127.0.0.1:30303"

for i in $(seq 1 "$N"); do
  p2p=$((30302 + i))
  rpc=$((8544 + i))
  boot=()
  [ "$i" -gt 1 ] && boot=(--bootnodes="$BOOTNODE")
  JAVA_OPTS="-Xmx${HEAP}" nohup "$BESU" \
    --data-path="$HERE/data/node$i" \
    --genesis-file="$HERE/generated/genesis.json" \
    --node-private-key-file="$HERE/data/node$i/key" \
    --p2p-host=127.0.0.1 --p2p-port="$p2p" \
    --rpc-http-enabled --rpc-http-host=127.0.0.1 --rpc-http-port="$rpc" \
    --rpc-http-api=ETH,NET,QBFT,WEB3,TXPOOL \
    --rpc-http-max-active-connections=2000 \
    --host-allowlist="*" --rpc-http-cors-origins="*" \
    --min-gas-price=0 \
    --tx-pool-max-future-by-sender=2000 \
    --metrics-enabled=false \
    --logging=WARN \
    "${boot[@]}" > "$HERE/logs/node$i.log" 2>&1 &
  echo $! > "$HERE/data/node$i/besu.pid"
  echo "node$i started (pid $!, rpc http://127.0.0.1:$rpc)"
  [ "$i" -eq 1 ] && sleep 5
done

# wait until node1 answers and blocks are being produced
for _ in $(seq 1 90); do
  bn=$(curl -s -X POST -H 'content-type: application/json' \
    --data '{"jsonrpc":"2.0","method":"eth_blockNumber","params":[],"id":1}' \
    http://127.0.0.1:8545 | sed -n 's/.*"result":"\(0x[0-9a-f]*\)".*/\1/p')
  if [ -n "$bn" ] && [ $((bn)) -gt 1 ]; then
    echo "network producing blocks (height $((bn)))"
    exit 0
  fi
  sleep 2
done
echo "network did not start producing blocks; see $HERE/logs" >&2
exit 1
